<?php

declare(strict_types=1);

namespace Saij\PluginDevTest\Post;

use Saij\WpAppFramework\Query\Field\IntField;
use Saij\WpAppFramework\Query\MetaFields;

/**
 * The fields of Rating for queries; generated by `wp-app-framework meta-fields`, change it as you like.
 */
